package com.aditya.chat.entity; import jakarta.persistence.*; @Entity @Table(name="users") public class AppUser{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true) String username; @Column(nullable=false) String password; protected AppUser(){} public AppUser(String u,String p){username=u;password=p;} public Long getId(){return id;} public String getUsername(){return username;} public String getPassword(){return password;}}
